.loading {
  padding: 24px 0;
  color: var(--bw-text-secondary);
  font-size: 14px;
  text-align: center;
}

.error {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 14px 16px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 14px;
}

.errorTitle {
  margin: 0;
  font-weight: 600;
}

.errorDetail {
  margin: 0;
  font-family: var(--bw-font-mono);
  font-size: 12px;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageButton:hover:not(:disabled):not(.pageActive) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageButton:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.pageButton.pageControl {
  color: var(--bw-input-placeholder);
}

.pageButton.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

.pageButton.pageActive:hover {
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
}

.pageSeparator {
  padding: 0 2px;
  color: var(--bw-input-placeholder);
}

