import { useEffect, useState } from 'react';
import type { KeyboardEvent } from 'react';
import { fetchThreadPage, pageCount } from '../../lib/threads';
import type { ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos.
 *
 * Pantalla propietaria del estado de búsqueda, página, carga y error. Llama a
 * `fetchThreadPage` con `profile.orgId`; `ThreadList` solo recibe datos ya
 * cargados y paginados.
 *
 * `onOpenThread` forma parte de la firma pública porque App.tsx la cablea
 * (F-118, corpus congelado), pero MSG-02 no se abre desde esta pantalla: la
 * prop se recibe y se ignora.
 */

const ELLIPSIS = '…' as const;
type PageItem = number | typeof ELLIPSIS;

/** Números de página a pintar, con elipsis cuando hay muchos. Los tests buscan
 *  cada página por su número como texto del botón, así que el número nunca va
 *  en un `aria-label` (F-145). */
function pagesAround(current: number, totalPages: number): PageItem[] {
  if (totalPages <= 7) {
    return Array.from({ length: totalPages }, (_, index) => index + 1);
  }
  const included = new Set<number>([1, totalPages, current - 1, current, current + 1]);
  const sorted = [...included]
    .filter((pageNumber) => pageNumber >= 1 && pageNumber <= totalPages)
    .sort((a, b) => a - b);
  const items: PageItem[] = [];
  let previous = 0;
  for (const pageNumber of sorted) {
    if (pageNumber - previous > 1) items.push(ELLIPSIS);
    items.push(pageNumber);
    previous = pageNumber;
  }
  return items;
}

/** El error de verdad, no un `[object Object]` (F-128): PostgREST rechaza con un
 *  objeto plano `{ code, message }`, así que hay que mirar dentro antes de
 *  rendirse a `String(error)`. */
function describeError(error: unknown): string {
  if (error instanceof Error) return error.message || String(error);
  if (typeof error === 'object' && error !== null) {
    const record = error as Record<string, unknown>;
    const code = typeof record.code === 'string' ? record.code : '';
    const message = typeof record.message === 'string' ? record.message : '';
    const details = typeof record.details === 'string' ? record.details : '';
    const parts = [code, message, details].filter((part) => part.length > 0);
    if (parts.length > 0) return parts.join(' · ');
  }
  return String(error);
}

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** Recibida por contrato de corpus (F-118); no se usa en MSG-01. */
  onOpenThread?: (threadId: string) => void;
}

export function Messages({
  profile,
  now = new Date(),
  onOpenThread: _onOpenThread,
}: MessagesProps) {
  const [search, setSearch] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [reloadTick, setReloadTick] = useState(0);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading');
  const [errorDetail, setErrorDetail] = useState<string | null>(null);

  useEffect(() => {
    let ignore = false;
    setStatus('loading');
    setErrorDetail(null);
    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((threadPage) => {
        if (ignore) return;
        setThreads(threadPage.threads);
        setTotal(threadPage.total);
        setStatus('ready');
      })
      .catch((error: unknown) => {
        if (ignore) return;
        setThreads([]);
        setTotal(0);
        setStatus('error');
        setErrorDetail(describeError(error));
      });
    return () => {
      ignore = true;
    };
  }, [profile.orgId, query, page, reloadTick]);

  const totalPages = pageCount(total);
  const loadingInitial = status === 'loading' && threads.length === 0;

  const submitSearch = () => {
    setQuery(search);
    setPage(1);
    setReloadTick((tick) => tick + 1);
  };

  const handleSearchKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      submitSearch();
    }
  };

  const goToPage = (nextPage: number) => {
    if (nextPage >= 1 && nextPage <= totalPages) setPage(nextPage);
  };

  const noop = () => {
    // MSG-02 no existe aún: abrir un hilo no lleva a ningún sitio, así que la
    // llamada de ThreadList se traga aquí. `onOpenThread` no se invoca.
  };

  return (
    <div className={styles.panel}>
      <header className={styles.header}>
        <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
        <h1 className={styles.pageTitle}>Hilos</h1>
        <p className={styles.pageSub}>
          Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
        </p>
      </header>

      <div className={styles.e2eeBar} role="status">
        <i className="ti ti-lock" aria-hidden="true" />
        <span>E2EE activo · cifrado de extremo a extremo</span>
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            onKeyDown={handleSearchKeyDown}
          />
        </div>

        <div className={styles.newContactWrap}>
          <button type="button" className={styles.primaryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.actionHint} data-testid="directorio-scope">
            Abre DIR-01 · fuera del MVP
          </span>
        </div>

        <span className={styles.threadCount} data-testid="pag-info">
          {total === 1 ? '1 hilo' : `${total.toLocaleString('es-ES')} hilos`} · Página{' '}
          {page.toLocaleString('es-ES')} de {totalPages.toLocaleString('es-ES')}
        </span>
      </div>

      {loadingInitial ? (
        <div className={styles.loading} role="status">
          Cargando hilos…
        </div>
      ) : status === 'error' ? (
        <div className={styles.error} role="alert">
          <p className={styles.errorTitle}>No se pudieron cargar los hilos.</p>
          {errorDetail ? <p className={styles.errorDetail}>{errorDetail}</p> : null}
        </div>
      ) : (
        <ThreadList threads={threads} now={now} onOpen={noop} />
      )}

      {total > 0 ? (
        <div className={styles.pagination}>
          <button
            type="button"
            className={`${styles.pageButton} ${styles.pageControl}`}
            aria-label="Página anterior"
            disabled={page <= 1}
            onClick={() => goToPage(page - 1)}
          >
            ‹
          </button>
          {pagesAround(page, totalPages).map((item, index) =>
            item === ELLIPSIS ? (
              <span key={`ellipsis-${index}`} className={styles.pageSeparator}>
                …
              </span>
            ) : (
              <button
                key={item}
                type="button"
                className={item === page ? `${styles.pageButton} ${styles.pageActive}` : styles.pageButton}
                aria-current={item === page ? 'page' : undefined}
                onClick={() => goToPage(item)}
              >
                {item}
              </button>
            ),
          )}
          <button
            type="button"
            className={`${styles.pageButton} ${styles.pageControl}`}
            aria-label="Página siguiente"
            disabled={page >= totalPages}
            onClick={() => goToPage(page + 1)}
          >
            ›
          </button>
        </div>
      ) : null}
    </div>
  );
}

