/* MSG-01 · filas de hilo y estado vacío.
   La paleta no define un blanco puro (el HTML aprobado usa #fff en tarjetas):
   las superficies de tarjeta usan --bw-warm-cream, el neutro de superficie
   clara más claro disponible como token. */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row + .row {
  border-top: 1px solid var(--bw-divider-mist);
}

/* La fila es un botón dentro del <li>: el <li> conserva así su rol listitem. */
.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 10px;
  row-gap: 4px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  background: none;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.rowButton:hover {
  background: var(--bw-row-hover-tint);
}

.rowButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  white-space: nowrap;
}

.rowMeta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  white-space: nowrap;
}

.time {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  flex: 1;
  overflow: hidden;
  font-size: 12px;
  color: var(--bw-text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  flex-shrink: 0;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
}

.stateNeutral {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.stateInfo {
  /* El token de chip azul es el de la familia del #2563EB del HTML aprobado. */
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.stateWarn {
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.stateSuccess {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.stateClosed {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

/* Estado vacío: contenedor propio, nunca un <li> ni dentro de un <ul> (F-141). */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 48px 28px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  text-align: center;
}

.emptyMessage {
  max-width: 420px;
  margin: 0;
  color: var(--bw-text-secondary);
  font-size: 14px;
  line-height: 1.6;
}

.emptyCta {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
  opacity: 0.5;
}

.emptyHint {
  margin: 0;
  color: var(--bw-input-placeholder);
  font-size: 12px;
}

