import { previewLabel, relativeTime, stateTone } from '../../lib/threads';
import type { StateTone, ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Recibe los hilos ya ordenados por la capa de datos y los pinta en ese orden;
 * no consulta ni pagina. La fila es un `<button>` DENTRO de un `<li>` para que
 * el `<li>` conserve su rol implícito `listitem`: un `role` añadido encima lo
 * sustituiría y rompería el contrato de accesibilidad (F-131).
 *
 * Con `threads` vacío no se pinta una lista vacía colgando, sino un estado vacío
 * fuera de cualquier `<ul>` (F-141), con su botón deshabilitado y el motivo
 * visible: el Directorio queda fuera del MVP.
 */

/** Tono → clase. `string | undefined` a propósito (F-143): una clase que falte
 *  en el módulo deja la fila sin adorno en vez de escribir `undefined` en el
 *  atributo `class`. */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.stateNeutral,
  info: styles.stateInfo,
  warn: styles.stateWarn,
  success: styles.stateSuccess,
  closed: styles.stateClosed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (threadId: string) => void;
}

export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMessage}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyCta} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        const toneClass = TONE_CLASS[tone] ?? '';
        return (
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                ) : null}
              </span>
              <span className={styles.rowMeta}>
                <time className={styles.time} dateTime={thread.lastItemAt}>
                  {relativeTime(thread.lastItemAt, now)}
                </time>
              </span>
              <span className={styles.rowBottom}>
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.stateBadge} ${toneClass}`.trim()}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
